"use client";

import * as React from "react";
import {
  Toaster as Sonner,
  toast,
  type ExternalToast,
  type ToasterProps,
} from "sonner";
import { Filters } from "@/components/ui/filters";
import { cn } from "@/lib/utils";

// ─── Design tokens per variant ───────────────────────────────────────────────

export type ComicToastVariant =
  | "default"
  | "success"
  | "error"
  | "warning"
  | "info";

export const variantTokens: Record<
  ComicToastVariant,
  { badge: string; bg: string; rotate: string; badgeBg: string }
> = {
  default: {
    badge: "HEY!",
    bg: "var(--toast-default-bg)",
    rotate: "-3deg",
    badgeBg: "var(--toast-default-badge-bg)",
  },
  success: {
    badge: "POW!",
    bg: "var(--toast-success-bg)",
    rotate: "3deg",
    badgeBg: "var(--toast-success-badge-bg)",
  },
  error: {
    badge: "ZAP!",
    bg: "var(--toast-error-bg)",
    rotate: "-4deg",
    badgeBg: "var(--toast-error-badge-bg)",
  },
  warning: {
    badge: "UH-OH!",
    bg: "var(--toast-warning-bg)",
    rotate: "2deg",
    badgeBg: "var(--toast-warning-badge-bg)",
  },
  info: {
    badge: "HMM...",
    bg: "var(--toast-info-bg)",
    rotate: "-2deg",
    badgeBg: "var(--toast-info-badge-bg)",
  },
};

// ─── Comic toast JSX ─────────────────────────────────────────────────────────

interface ComicToastProps {
  title: React.ReactNode;
  description?: React.ReactNode;
  variant?: ComicToastVariant;
  containerClassName?: string;
}

export function ComicToast({
  title,
  description,
  variant = "default",
  containerClassName,
}: ComicToastProps) {
  const { badge, bg, rotate, badgeBg } = variantTokens[variant];
  const isDark = ["success", "error", "warning", "info"].includes(variant);
  const textColor = isDark ? "white" : "light-dark(black, white)";

  return (
    <Filters.Displacement scale={2} frequency={0.65}>
      <div
        style={{
          backgroundImage: `radial-gradient(circle, rgba(0,0,0,0.25) 1.2px, transparent 1.2px)`,
          backgroundSize: "8px 8px",
          backgroundColor: bg,
        }}
        className={cn(
          "relative w-full px-3 pb-3 pt-5 border-4 border-foreground box-border shadow-[10px_10px_0_var(--foreground)]",
          containerClassName,
        )}
      >
        {/* Exclamation badge — top-right corner */}
        <span
          aria-hidden
          style={{
            position: "absolute",
            top: "-14px",
            right: "10px",
            backgroundColor: badgeBg,
            border: "3px solid black",
            borderRadius: "4px",
            padding: "1px 8px",
            fontFamily: "'Bangers', cursive",
            fontSize: "14px",
            letterSpacing: "0.08em",
            color: "black",
            transform: `rotate(${rotate})`,
            boxShadow: "3px 3px 0 rgba(0,0,0,0.85)",
            zIndex: 10,
            whiteSpace: "nowrap",
            lineHeight: 1.4,
          }}
        >
          {badge}
        </span>

        {/* Title */}
        <div
          style={{
            fontFamily: "'Bangers', cursive",
            fontSize: "20px",
            letterSpacing: "0.05em",
            color: textColor,
            lineHeight: 1.2,
            marginBottom: description ? "6px" : 0,
            textShadow: isDark ? "1px 1px 0 rgba(0,0,0,0.4)" : "none",
          }}
        >
          {title}
        </div>

        {/* Description — solid pill for legibility over halftone */}
        {description && (
          <div
            style={{
              display: "inline-block",
              backgroundColor: "rgba(255,255,255,0.92)",
              border: "2px solid black",
              borderRadius: "3px",
              padding: "3px 8px",
              fontFamily: "'Walter Turncoat', cursive",
              fontSize: "13px",
              color: "black",
              lineHeight: 1.4,
            }}
          >
            {description}
          </div>
        )}
      </div>
    </Filters.Displacement>
  );
}

// ─── Convenience fire functions ───────────────────────────────────────────────

function fireComicToast(
  variant: ComicToastVariant,
  title: React.ReactNode,
  description?: React.ReactNode,
  data?: ExternalToast & { containerClassName?: string },
) {
  toast.custom(
    () => (
      <ComicToast
        title={title}
        description={description}
        variant={variant}
        containerClassName={data?.containerClassName}
      />
    ),
    data,
  );
}

type TComicToastFunc = (
  title: React.ReactNode,
  description?: React.ReactNode,
  data?: ExternalToast & {
    containerClassName?: string;
  },
) => void;

const comicToastCurry =
  (variant: ComicToastVariant) =>
  (
    title: React.ReactNode,
    description?: React.ReactNode,
    data?: ExternalToast & { containerClassName?: string },
  ) =>
    fireComicToast(variant, title, description, data);

export const comicToast: {
  default: TComicToastFunc;
  success: TComicToastFunc;
  error: TComicToastFunc;
  warning: TComicToastFunc;
  info: TComicToastFunc;
} = {
  default: comicToastCurry("default"),
  success: comicToastCurry("success"),
  error: comicToastCurry("error"),
  warning: comicToastCurry("warning"),
  info: comicToastCurry("info"),
};

// ─── Toaster (place once in app root) ────────────────────────────────────────

const Toaster = ({ ...props }: ToasterProps) => {
  return (
    <Sonner
      position="bottom-right"
      style={{ "--width": "340px" } as React.CSSProperties}
      {...props}
    />
  );
};

export { Toaster };
